#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define R3(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H3(t)(cos((vec3(0,2,-2)/3.+t)*6.24)*.5+.5)
#define D(a)length(vec2(fract(log(length(a.xy))+iTime*.5)-.5,a.z))/3.-.005*pow(l,.03)
void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  

       vec4 O3=O;
      O3=vec4(0);
    vec3 n2,u,r3=iResolution,d3=normalize(vec3(C-.5*r.xy,r.y));
    for(float i=0.,e,g=0.,t=iTime*0.,z,f;
        i++<80.;
        O3.xyz+=mix(vec3(1),H(z),.6)*.05/exp(.3*i*i*e)
    ){
       n2=d3*g,
         z=n2.z+t;
        n2.z-=1.5,

        n2=R(n2,normalize(H(t*.02)-.5),1.5);

        n2.z+=iTime*0.5;
        u=floor((n2-2.)/4.);
        u=sin(9.*(2.6*u+3.*u.yzx+1e-3));
         u.zy*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
          u.xy*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
        f=dot(u,u.yxz);
        n2=(mod(n2-2.,4.)-2.);
        n2.z=mod(n2.z+atan(n2.y,n2.x)/acos(-1.)*.2,.4)-.2;
        g+=e=abs(length(vec2(length(n2.xy)-.4,n2.z))-.04)+.01*(sin(z+f+t)*.5+.5);
    }
     vec4 O2=O;



         O=vec4(0);
    vec3 n1,r2=iResolution;
    for(float g,e,i=0.,l;
        ++i<99.;
        e<.005?O2.xyz+=mix(vec3(1),H(l),.7)/i:n1
        )
    {
        n1=R(g*normalize(vec3((C-.5*r2.xy)/r2.y,1.))-vec3(0,0,6),
            normalize(vec3(1,2,0)),
            -iTime*.2
        );
        l=length(n1);
        g+=e=min(min(D(n1),D(n1.zxy)),D(n1.yzx));    
    }
    for(float i=0.,a,s,e,g=0.,l;
        ++i<70.;
        O.xyz+=mix(vec3(0.1,1.,3.1),H(g*.1),.8)*3./e/8e3
    )
    {
        p=g*d+O2.xyz;

  p.z+=iTime;

        a=30.;

        p=mod(p-a,a*2.)-a;
        s=2.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.01)*.1;
            p=abs(p)*e-
                vec3(
                    4.*3.,
                    120,
                    5.*5.
                 )*O3.xyz;

         }
         g+=e=length(p.yzzz)/s;

    }
}
